const picture=(scene,label)=>`<svg viewBox="0 0 560 180" role="img" aria-label="${label}" class="academy-diagram"><rect width="560" height="180" rx="18" fill="#16363e"/><g fill="#abcfc5"><circle cx="30" cy="34" r="2"/><circle cx="210" cy="23" r="2"/><circle cx="520" cy="55" r="2"/></g>${scene}</svg>`;
const buddy='<rect x="240" y="66" width="78" height="64" rx="15" fill="#edd5a0"/><rect x="251" y="80" width="56" height="27" rx="10" fill="#234854"/><g fill="#9df2e4"><circle cx="266" cy="93" r="6"/><circle cx="292" cy="93" r="6"/></g><path d="M250 130v15m56-15v15" stroke="#aecac2" stroke-width="8"/>';
export const ACADEMY_PAGES=[
 {title:'Pick Your World!',art:picture('<g class="storybook-worlds"><circle cx="120" cy="86" r="46" fill="#d4a35b"/><path d="M80 92q40-20 80 0" stroke="#956647" fill="none" stroke-width="8"/><circle cx="280" cy="86" r="46" fill="#c3ccc6"/><g fill="#7c9097"><circle cx="261" cy="73" r="12"/><circle cx="299" cy="99" r="16"/></g><circle cx="440" cy="86" r="46" fill="#ce825b"/><path d="M407 90l27-15 10 22 29-12" stroke="#945b48" fill="none" stroke-width="9"/></g><g fill="#fff0c5" font-size="17" text-anchor="middle"><text x="120" y="158">TITAN</text><text x="280" y="158">MOON</text><text x="440" y="158">MARS</text></g>','Titan, Moon and Mars'),body:'Where will Voyager explore today? Sail Titan’s methane seas, visit the Moon’s icy shadowed craters, or drive across an ancient river delta on Mars!'},
 {title:'Build Your Explorer!',art:picture(buddy+'<path d="M235 68q44-57 88 0z" fill="#ffc94f"/><path d="M232 68h95" stroke="#ffe799" stroke-width="8"/><g fill="#e7eadb" stroke="#75acb3" stroke-width="3"><path d="M85 125V82q15-40 30 0v43z"/><path d="M155 125V60q18-48 36 0v65z"/><path d="M393 135V46q25-52 50 0v89z"/></g><g fill="#f0ba68"><circle cx="477" cy="86" r="17"/><circle cx="507" cy="118" r="17"/></g>','Voyager in a hardhat beside three rocket sizes and coins'),body:'Pack a rocket, power, radio, and science tools. Watch your coins and rocket weight! If your ship is too heavy, choose lighter tools or a bigger rocket.'},
 {title:'Blast Off & Dodge Space Rocks!',art:picture('<g class="storybook-capsule"><path d="M135 102q48-75 109-12-55 65-109 12" fill="#d5e7de" stroke="#f1cc84" stroke-width="4"/><ellipse cx="210" cy="92" rx="10" ry="14" fill="#7de6e1"/><path d="M132 91l-49 12 49 9" fill="#71d4f1"/></g><g fill="#9c8975" stroke="#d9c0a1" stroke-width="4"><path d="M372 34l33 19 15 39-37 23-35-29z"/><path d="M458 120l20-17 32 17-14 29-33-2z"/></g><path d="M280 85q30-55 59-28" stroke="#ffe29a" fill="none" stroke-width="4" stroke-dasharray="8 8"/>','Capsule steering around asteroids with blue thrusters'),body:'Hold the big button to launch! In space, steer with Arrow keys or W/A/S/D. Dodge rocks and space junk until you arrive. Want a shortcut? Tap Skip to Landing.'},
 {title:'Make Historic Discoveries!',art:picture(buddy+'<path d="M341 142V45" stroke="#d7e8dd" stroke-width="5"/><path d="M344 45h58l-12 19 12 19h-58" fill="#f2c975"/><path d="M320 88q49-63 105-45" stroke="#a4e9dc" stroke-width="3" stroke-dasharray="6 7" fill="none"/><circle cx="452" cy="44" r="25" fill="#4791bf"/><path d="M438 27l13 12 16-5-4 21-15 7-9-12z" fill="#a8cda8"/><path d="M80 148h400" stroke="#b3c2ae" stroke-width="5"/>','Voyager planting a flag and sending discoveries to Earth'),body:'Follow glowing markers! Measure moonquakes, sample lake liquids, and take pictures. Collect five discoveries, then radio them home to Earth to earn your mission medal!'}
];
export const academyPage=index=>Math.max(0,Math.min(ACADEMY_PAGES.length-1,Number.isFinite(index)?Math.trunc(index):0));
export function academyMarkup(index=0){const n=academyPage(index),p=ACADEMY_PAGES[n];return `<section class="academy-page"><span class="tiny-label">EXPLORER STORYBOOK · ${n+1} / 4</span><h3>${p.title}</h3>${p.art}<p>${p.body}</p></section><div class="academy-navigation"><button data-game="academy-page" data-page="${n-1}" ${n===0?'disabled':''}>⬅ Back</button><span aria-label="Page ${n+1} of 4">${ACADEMY_PAGES.map((_,i)=>`<span ${i===n?'aria-current="page"':''}>${i===n?'●':'○'}</span>`).join(' ')}</span><button data-game="academy-page" data-page="${n+1}" ${n===3?'disabled':''}>Next ➔</button></div><button class="play-button" data-game="close">Let’s Play! 🚀</button>`;}
